const question = (id, text, options, correct, explanation) => ({
  id,
  type: 'multiple-choice',
  text,
  options: options.map((option, index) => ({ id: `${id}-option-${index + 1}`, text: option })),
  correctOptionId: `${id}-option-${options.indexOf(correct) + 1}`,
  correctAnswer: '',
  marks: 1,
  explanation,
})

const lesson = (intro, sections) => ({ intro, sections })

const makeQuiz = ({ id, title, category, difficulty, color, description, image, learningContent, questions }) => ({
  id: `sample-${id}`,
  title,
  category,
  difficulty,
  color,
  description,
  image,
  estimatedTime: 15,
  timeLimit: 15,
  instructions: 'Choose one answer for each question. You can move between questions and review your choices before submitting.',
  shuffleQuestions: false,
  shuffleAnswers: false,
  isSample: true,
  learningContent,
  questions: questions.map(([text, options, correct, explanation], index) => {
    const correctIndex = (index * 3 + 1) % options.length
    const answerChoices = options.filter((option) => option !== correct)
    answerChoices.splice(correctIndex, 0, correct)
    return question(`${id}-question-${index + 1}`, text, answerChoices, correct, explanation)
  }),
})

